    /// Everything to the end of the files (replay), the unfinished last lines included.
    pub fn read_all(&mut self) -> Result<Vec<UsageTurn>, IngestError> {
        let mut turns = Vec::new();
        loop {
            turns.extend(self.next_batch()?);
            if self.at_eof() {
